-- Каталог КИЦУНЭ: меню из дизайна (frontend). sku — стабильный идентификатор
-- из дизайна (data-add), по нему фронтенд резолвит позицию в backend.

ALTER TABLE products ADD COLUMN IF NOT EXISTS sku TEXT;

